
INSERT INTO public.jobs (title, slug, company_id, posted_by, category, location, job_type, experience_level, description, requirements, responsibilities, salary_min, salary_max, salary_currency, skills, is_active, is_featured)
VALUES
('Network Engineer', 'network-engineer-albtelecom', '9d787199-4293-4be8-b18e-893fc8f9875d', '2ae25656-f7bd-499f-a945-71f8fb277710', 'IT & Technology', 'Tirana, Albania', 'full_time', 'mid', 'ALBtelecom is seeking a skilled Network Engineer to design, implement, and maintain our telecommunications infrastructure across Albania. You will work with cutting-edge fiber optic and wireless technologies.', 'Bachelor''s degree in Computer Science or Telecommunications. 3+ years of network engineering experience. CCNA/CCNP certification preferred. Strong knowledge of TCP/IP, BGP, OSPF, and MPLS.', 'Design and implement network solutions. Monitor network performance and troubleshoot issues. Manage router and switch configurations. Collaborate with cross-functional teams on infrastructure projects.', 80000, 120000, 'ALL', ARRAY['Cisco', 'Networking', 'TCP/IP', 'Fiber Optics', 'Linux'], true, false),

('Mobile App Developer', 'mobile-app-developer-one', '77cc61e0-a87a-4ea8-bdd2-836b81534692', '2ae25656-f7bd-499f-a945-71f8fb277710', 'IT & Technology', 'Tirana, Albania', 'full_time', 'mid', 'ONE Telecommunications is looking for a talented Mobile App Developer to build and enhance our customer-facing mobile applications for Android and iOS platforms.', 'Bachelor''s degree in Computer Science. 2+ years of mobile development experience. Proficiency in React Native or Flutter. Experience with RESTful APIs and mobile UI/UX best practices.', 'Develop and maintain mobile applications. Implement new features and optimize performance. Write clean, testable code. Collaborate with designers and backend engineers.', 90000, 140000, 'ALL', ARRAY['React Native', 'Flutter', 'JavaScript', 'iOS', 'Android'], true, true),

('Petroleum Engineer', 'petroleum-engineer-bankers', '97957ec8-201a-4a45-8526-2803b84a0e9d', '2ae25656-f7bd-499f-a945-71f8fb277710', 'Engineering', 'Fier, Albania', 'full_time', 'senior', 'Bankers Petroleum is hiring a Senior Petroleum Engineer to oversee oil production operations and optimize extraction processes at our Albanian oilfields.', 'Master''s degree in Petroleum Engineering. 5+ years of upstream oil & gas experience. Strong knowledge of reservoir simulation and production optimization. Willingness to work in field locations.', 'Manage daily production operations. Analyze reservoir data and optimize well performance. Lead well intervention and workover programs. Ensure compliance with safety and environmental regulations.', 200000, 350000, 'ALL', ARRAY['Petroleum Engineering', 'Reservoir Simulation', 'Production Optimization', 'HSE'], true, false),

('Business Development Manager', 'business-development-kastrati', 'e9e16d9e-260d-4694-b6cd-009e4d3cbf0c', '2ae25656-f7bd-499f-a945-71f8fb277710', 'Sales & Marketing', 'Durrës, Albania', 'full_time', 'senior', 'Kastrati Group is seeking an experienced Business Development Manager to identify growth opportunities and expand our market presence across construction, tourism, and retail sectors.', '5+ years of business development experience. Strong network in Albanian business community. Excellent negotiation and presentation skills. MBA or equivalent preferred.', 'Identify and pursue new business opportunities. Build and maintain strategic partnerships. Develop market entry strategies for new sectors. Prepare business proposals and presentations.', 150000, 250000, 'ALL', ARRAY['Business Development', 'Sales', 'Negotiation', 'Strategic Planning'], true, true),

('Credit Risk Analyst', 'credit-risk-analyst-credins', '27c4a63f-c557-4afa-b5e2-34941e752ba9', '2ae25656-f7bd-499f-a945-71f8fb277710', 'Finance & Accounting', 'Tirana, Albania', 'full_time', 'mid', 'Credins Bank is looking for a Credit Risk Analyst to assess and manage credit risk exposure, develop risk models, and support lending decisions.', 'Bachelor''s degree in Finance, Economics, or Mathematics. 3+ years of credit risk analysis experience. Proficiency in statistical modeling and Excel. Knowledge of Basel III regulations.', 'Evaluate creditworthiness of loan applicants. Develop and maintain credit risk models. Monitor portfolio risk metrics and prepare reports. Support regulatory compliance activities.', 100000, 160000, 'ALL', ARRAY['Risk Analysis', 'Financial Modeling', 'Excel', 'SQL', 'Basel III'], true, false),

('HSE Manager', 'hse-manager-albpetrol', '0bc7ac82-260b-4aa0-8d90-3e7a193f8927', '2ae25656-f7bd-499f-a945-71f8fb277710', 'Engineering', 'Fier, Albania', 'full_time', 'senior', 'Albpetrol is hiring an HSE Manager to lead health, safety, and environmental programs across our oil production facilities in Albania.', '5+ years of HSE management experience in oil & gas. NEBOSH or equivalent certification. Strong knowledge of Albanian and EU environmental regulations. Leadership experience managing safety teams.', 'Develop and implement HSE policies and procedures. Conduct risk assessments and safety audits. Lead incident investigations and corrective actions. Train staff on safety protocols and compliance.', 160000, 250000, 'ALL', ARRAY['HSE Management', 'NEBOSH', 'Risk Assessment', 'Environmental Compliance'], true, false),

('Content Producer', 'content-producer-digitalb', '0bbe9cd0-f7d3-4fc9-a8f2-da056a424e20', '2ae25656-f7bd-499f-a945-71f8fb277710', 'Media & Communications', 'Tirana, Albania', 'full_time', 'mid', 'Digitalb is seeking a creative Content Producer to develop engaging TV and digital content for our growing audience across Albania and the Balkans.', '3+ years of content production experience. Strong storytelling and scriptwriting skills. Experience with video editing software (Premiere Pro, DaVinci Resolve). Fluent in Albanian and English.', 'Produce original content for TV and digital platforms. Manage production schedules and budgets. Collaborate with directors, editors, and on-screen talent. Research trending topics and audience interests.', 70000, 110000, 'ALL', ARRAY['Content Production', 'Video Editing', 'Storytelling', 'Adobe Premiere', 'Albanian'], true, false),

('Quality Control Engineer', 'qc-engineer-antea-cement', '9bdd741c-ea8a-43d7-8565-e24f1ae69db4', '2ae25656-f7bd-499f-a945-71f8fb277710', 'Engineering', 'Elbasan, Albania', 'full_time', 'mid', 'Antea Cement is looking for a Quality Control Engineer to ensure product quality standards across our cement manufacturing operations.', 'Bachelor''s degree in Chemical or Materials Engineering. 2+ years of QC experience in manufacturing. Knowledge of ISO 9001 and cement testing standards. Strong analytical and problem-solving skills.', 'Conduct quality tests on raw materials and finished products. Maintain quality management systems and documentation. Investigate quality issues and implement corrective actions. Ensure compliance with ISO and industry standards.', 80000, 120000, 'ALL', ARRAY['Quality Control', 'ISO 9001', 'Manufacturing', 'Chemical Engineering', 'Lab Testing'], true, false),

('Airport Operations Supervisor', 'operations-supervisor-tia', 'f93427d0-e8ff-4b0f-8f6d-6531396cf395', '2ae25656-f7bd-499f-a945-71f8fb277710', 'Operations & Logistics', 'Tirana, Albania', 'full_time', 'mid', 'Tirana International Airport is hiring an Operations Supervisor to oversee daily airport operations ensuring safe, efficient, and passenger-friendly services.', '3+ years of airport or aviation operations experience. Knowledge of IATA and ICAO standards. Strong leadership and communication skills. Fluent in Albanian and English; additional languages a plus.', 'Supervise daily airside and landside operations. Coordinate with airlines, ground handlers, and security. Manage operational disruptions and implement contingency plans. Ensure compliance with aviation safety regulations.', 90000, 140000, 'ALL', ARRAY['Airport Operations', 'Aviation', 'IATA', 'Team Leadership', 'Safety'], true, true),

('Store Manager', 'store-manager-neptun', 'b192f1ff-121c-49d9-9f6f-cc37537de278', '2ae25656-f7bd-499f-a945-71f8fb277710', 'Retail & Sales', 'Tirana, Albania', 'full_time', 'mid', 'Neptun is seeking an experienced Store Manager to lead one of our flagship electronics retail stores in Tirana, driving sales and delivering excellent customer experiences.', '3+ years of retail management experience. Strong knowledge of electronics and consumer technology. Proven track record in sales target achievement. Excellent Albanian and English communication skills.', 'Manage daily store operations and staff schedules. Drive sales performance and meet revenue targets. Train and develop sales team members. Maintain visual merchandising and inventory standards.', 70000, 100000, 'ALL', ARRAY['Retail Management', 'Sales', 'Customer Service', 'Team Leadership', 'Electronics'], true, false);
